"""Complete pole strata and interpolation from a supplied signed relation."""
from collections import Counter
import quotient as q


def point(curve,P,allow_identity=True):
    p,f=q.curve_data(curve)
    if P is None:
        q.require(allow_identity,'affine summand required'); return None
    q.require(type(P) in (list,tuple) and len(P)==2,'point representation')
    x,y=P; q.scalar(x,p);q.scalar(y,p)
    q.require(y*y % p==q.evaluate(f,x,p),'point on curve')
    return (x,y)


def add_points(curve,P,Q):
    q.event('elliptic_group_add')
    p=curve['p']
    if P is None:return Q
    if Q is None:return P
    x,y=P;u,v=Q
    if x==u and (y+v)%p==0:return None
    if x==u:
        slope=(3*x*x+curve['a'])*q.inv(2*y,p)%p
    else:slope=(v-y)*q.inv(u-x,p)%p
    z=(slope*slope-x-u)%p
    return (z,(slope*(x-z)-y)%p)


def sum_points(curve,points):
    total=None
    for P in points:total=add_points(curve,total,P)
    return total


def basis(d):
    terms=[('A',i,2*i) for i in range(d//2+1)]
    terms += [('B',j,2*j+3) for j in range(max(0,(d-3)//2+1))]
    return sorted(terms,key=lambda t:t[2])


def chart_spec(curve,k,target):
    q.event('chart_specification'); q.curve_data(curve); q.integer(k,'affine arity')
    q.require(k<=5,'five summand scope');target=point(curve,target)
    if k==0:return {'possible':target is None,'d':0,'special':'all_identity' if target is None else 'finite_zero_impossible'}
    d=k+int(target is not None)
    if d==1:return {'possible':False,'d':1,'special':'no_pole_one'}
    return {'possible':True,'d':d,'c':1 if d%2==0 else -1,'basis':basis(d)}


def trunc(a,L):
    return (a+[0]*L)[:L]


def smul(a,b,p,L):
    return trunc(q.mul(a,b,p),L)


def compose(a,x,p,L):
    v=[0]*L
    for c in reversed(a):
        v=smul(v,x,p,L);v[0]=(v[0]+c)%p
    return v


def interpolation_series(curve,P,L):
    p,f=q.curve_data(curve);alpha,beta=P
    if beta:
        x=trunc([alpha,1],L); y=[beta]+[0]*(L-1);F=compose(f,x,p,L);den=q.inv(2*beta,p)
        for n in range(1,L):y[n]=(F[n]-sum(y[i]*y[n-i] for i in range(1,n)))*den%p
    else:
        x=[alpha]+[0]*(L-1);y=trunc([0,1],L);den=q.inv(3*alpha*alpha+curve['a'],p)
        for n in range(1,L):
            value=compose(f,x,p,L)[n];x[n]=((int(n==2)-value)*den)%p
    return x,y


def unique_linear_solution(rows,rhs,p,n):
    q.event('interpolation_gaussian_elimination')
    M=[a[:]+[b] for a,b in zip(rows,rhs)];row=0;pivots=[]
    for col in range(n):
        pivot=next((i for i in range(row,len(M)) if M[i][col]),None)
        if pivot is None:continue
        M[row],M[pivot]=M[pivot],M[row];den=q.inv(M[row][col],p)
        M[row]=[a*den%p for a in M[row]]
        for i in range(len(M)):
            if i!=row:
                c=M[i][col];M[i]=[(a-c*b)%p for a,b in zip(M[i],M[row])]
        pivots.append(col);row+=1
    q.require(all(any(a[:n]) or a[n]==0 for a in M),'consistent interpolation')
    q.require(len(pivots)==n,'unique normalized interpolation')
    out=[0]*n
    for i,col in enumerate(pivots):out[col]=M[i][-1]
    return out


def construct_from_signed_multiset(curve,interval,points,target):
    q.event('relation_witness_constructor');p,f=q.curve_data(curve)
    q.require(type(interval) is dict and set(interval)=={'t','s'},'interval representation')
    t,s=interval['t'],interval['s'];q.interval(p,t,s)
    q.require(type(points) is list,'signed point list')
    pts=[point(curve,P,False) for P in points];target=point(curve,target);k=len(pts)
    for x,y in pts:q.require((x-t)%p < 1<<s,'supplied point interval')
    spec=chart_spec(curve,k,target);q.require(spec['possible'],'possible pole chart')
    q.require(sum_points(curve,pts)==target,'supplied relation group sum')
    if not k:
        return {'curve':dict(curve),'interval':dict(interval),'k':0,'target':None,'A':[1],'B':[0],'U':{'p':p,'coeffs':[1]},'e':[],'root_lifts':[]}
    d=spec['d'];zeros=Counter(pts)
    if target is not None:zeros[(target[0],(-target[1])%p)]+=1
    rows=[];rhs=[];terms=spec['basis']
    for P,m in sorted(zeros.items()):
        x,y=interpolation_series(curve,P,d+1);values=[]
        for kind,i,_ in terms:
            v=[1]+[0]*d
            for _ in range(i):v=smul(v,x,p,d+1)
            if kind=='B':v=smul(v,y,p,d+1)
            values.append(v)
        for j in range(m):
            rows.append([v[j] for v in values[:-1]]);rhs.append(-values[-1][j]%p)
    coefs=unique_linear_solution(rows,rhs,p,len(terms)-1)+[1];A=[0]*(d//2+1);B=[0]*max(1,(d-3)//2+1)
    for (kind,i,_),c in zip(terms,coefs):(A if kind=='A' else B)[i]=c
    A=q.trim(A);B=q.trim(B);N=q.sub(q.mul(A,A,p),q.mul(f,q.mul(B,B,p),p),p);u=q.scale(N,spec['c'],p)
    if target is not None:u=q.exact(u,[(-target[0])%p,1],p)
    U={'p':p,'coeffs':u};q.require(len(u)==k+1 and u[-1]==1,'residual degree and normalization')
    support=Counter(P[0] for P in pts);e=[[0] for _ in range(s)]
    for x,m in sorted(support.items()):
        q.event('CRT_local_factor');local=q.power([(-x)%p,1],m,p);other=q.exact(u,local,p)
        projector=q.rem(q.mul(other,q.inverse_mod(other,local,p),p),u,p);label=(x-t)%p
        for j in range(s):
            if label>>j&1:e[j]=q.rem(q.add(e[j],projector,p),u,p)
    q.verify_quotient_witness(U,t,s,e,curve)
    roots=sorted(set(pts+([target] if target is not None else [])))
    return {'curve':dict(curve),'interval':dict(interval),'k':k,'target':list(target) if target else None,'A':A,'B':B,'U':U,'e':e,'root_lifts':[list(P) for P in roots]}

"""Recompute signed orders by bounded local series, not producer valuations."""
from collections import Counter
import quotient as q
from projectors import check_factor_certificate


def _point(P,curve):
    p,f=q.curve_data(curve)
    q.require(type(P) is list and len(P)==2,'checker point representation')
    x,y=P;q.scalar(x,p);q.scalar(y,p)
    q.require(y*y%p==q.evaluate(f,x,p),'checker point on curve')
    return x,y


def _series_product(a,b,p,L):
    out=[0]*L
    for i,x in enumerate(a):
        for j,y in enumerate(b[:L-i]):out[i+j]=(out[i+j]+x*y)%p
    return out


def _series_eval(poly,x,p,L):
    out=[0]*L
    for c in reversed(poly):
        out=_series_product(out,x,p,L);out[0]=(out[0]+c)%p
    return out


def local_order(curve,P,A,B,d):
    """Hasse coefficient recurrence in x-alpha or y, through order d."""
    q.event('checker_local_series');p,f=q.curve_data(curve);alpha,beta=P;L=d+1
    if beta:
        x=[alpha,1]+[0]*(L-2);y=[beta]+[0]*(L-1);F=_series_eval(f,x,p,L)
        for j in range(1,L):
            known=sum(y[i]*y[j-i] for i in range(1,j))%p
            y[j]=(F[j]-known)*q.inv(2*beta,p)%p
    else:
        y=[0,1]+[0]*(L-2);x=[alpha]+[0]*(L-1)
        derivative=(3*alpha*alpha+curve['a'])%p
        for j in range(1,L):
            previous=_series_eval(f,x,p,L)[j]
            x[j]=(int(j==2)-previous)*q.inv(derivative,p)%p
    aa=_series_eval(A,x,p,L);bb=_series_product(_series_eval(B,x,p,L),y,p,L)
    coefficients=[(a+b)%p for a,b in zip(aa,bb)]
    order=next((i for i,c in enumerate(coefficients) if c),None)
    q.require(order is not None,'checker finite local order within pole bound')
    return order


def _sum(curve,points):
    """Checker's own affine accumulation, including identity/torsion branches."""
    p=curve['p'];total=None
    for P in points:
        q.event('checker_group_add')
        if total is None:total=P;continue
        x,y=total;u,v=P
        if x==u and (y+v)%p==0:total=None;continue
        numerator=(3*x*x+curve['a']) if total==P else (v-y)
        denominator=(2*y) if total==P else (u-x)
        slope=numerator*q.inv(denominator,p)%p
        xx=(slope*slope-x-u)%p;total=(xx,(slope*(x-xx)-y)%p)
    return total


def _verify(w,recovered):
    q.event('independent_chart_check')
    required={'curve','interval','k','target','A','B','U','e','root_lifts'}
    q.require(type(w) is dict and required<=set(w) and set(w)<=required|{'factors'},'witness shape')
    curve=w['curve'];p,f=q.curve_data(curve);up,u=q.modulus(w['U']);q.require(up==p,'checker field binding')
    q.require(type(w['interval']) is dict and set(w['interval'])=={'t','s'},'checker interval representation')
    t,s=w['interval']['t'],w['interval']['s'];q.interval(p,t,s)
    k=q.integer(w['k'],'checker affine arity');q.require(k<=5 and len(u)==k+1,'checker quotient degree')
    A=q.canonical(w['A'],p);B=q.canonical(w['B'],p)
    target=_point(w['target'],curve) if w['target'] is not None else None
    q.require(type(recovered) is list and len(recovered)==5,'five point output')
    pts=[_point(P,curve) for P in recovered if P is not None]
    q.require(len(pts)==k and recovered==[list(P) for P in sorted(pts)]+[None]*(5-k),'canonical multiset and padding')
    for x,y in pts:q.require((x-t)%p < 1<<s,'checker residual interval')
    cert={'p':p,'t':t,'s':s,'factors':[[x,m] for x,m in sorted(Counter(x for x,y in pts).items())]}
    check_factor_certificate(w['U'],cert)
    if 'factors' in w:
        check_factor_certificate(w['U'],w['factors']);q.require(w['factors']==cert,'factor output binding')
    q.verify_quotient_witness(w['U'],t,s,w['e'],curve)
    q.require(type(w['root_lifts']) is list,'checker lift list')
    for P in w['root_lifts']:_point(P,curve)
    if not k:
        q.require(target is None and A==[1] and B==[0],'all identity special chart');return
    d=k+int(target is not None);q.require(d>=2,'checker no pole one')
    da=-1 if A==[0] else len(A)-1;db=-1 if B==[0] else len(B)-1
    if d%2==0:q.require(2*da==d and A[-1]==1 and (B==[0] or 2*db+3<d),'checker even pole shape')
    else:q.require(2*db+3==d and B[-1]==1 and (A==[0] or 2*da<d),'checker odd pole shape')
    norm=q.sub(q.mul(A,A,p),q.mul(f,q.mul(B,B,p),p),p)
    lhs=q.scale(norm,1 if d%2==0 else -1,p)
    rhs=q.mul([(-target[0])%p,1],u,p) if target else u
    q.require(lhs==rhs,'checker norm identity')
    zeros=Counter(pts)
    if target:zeros[(target[0],(-target[1])%p)]+=1
    q.require(sum(zeros.values())==d,'checker signed degree')
    for P,m in zeros.items():q.require(local_order(curve,P,A,B,d)==m,'checker exact signed local order')
    q.require(_sum(curve,pts)==target,'checker group relation')


def check_chart(witness,recovered):
    try:
        _verify(witness,recovered)
        return {'status':'valid','obligation':None}
    except (q.ObligationError,KeyError,TypeError,IndexError) as error:
        return {'status':'invalid','obligation':str(error),'exception_type':type(error).__name__}
    except Exception as error:
        return {'status':'error','obligation':str(error),'exception_type':type(error).__name__}

"""Canonical prime-field polynomial arithmetic; primality is a mathematical premise."""
EVENTS = {}


def event(name, count=1):
    EVENTS[name] = EVENTS.get(name, 0) + count


class ObligationError(ValueError):
    pass


def require(condition, obligation):
    if not condition:
        raise ObligationError(obligation)


def integer(x, name, minimum=0):
    require(type(x) is int and x >= minimum, name)
    return x


def field(p):
    return integer(p, 'prime modulus premise', 2)


def scalar(x, p):
    require(type(x) is int and 0 <= x < p, 'canonical field element')
    return x


def canonical(a, p):
    require(type(a) is list and len(a) > 0, 'polynomial representation')
    for x in a:
        scalar(x, p)
    require(len(a) == 1 or a[-1] != 0, 'trailing polynomial zero')
    return a[:]


def modulus(U):
    require(type(U) is dict and set(U) == {'p', 'coeffs'}, 'quotient field binding')
    p = field(U['p']); u = canonical(U['coeffs'], p)
    require(u[-1] == 1, 'monic quotient modulus')
    return p, u


def interval(p, t, s):
    scalar(t, p); integer(s, 'interval bit count')
    require(s < p.bit_length() and (1 << s) < p, 'injective interval length')


def trim(a):
    a = list(a)
    while len(a) > 1 and not a[-1]:
        a.pop()
    return a or [0]


def add(a, b, p):
    event('polynomial_add')
    return trim([((a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)) % p
                 for i in range(max(len(a), len(b)))])


def scale(a, c, p):
    event('polynomial_scale')
    return trim([x*c % p for x in a])


def sub(a, b, p):
    return add(a, scale(b, -1, p), p)


def inv(a, p):
    event('field_inversion')
    require(a % p != 0, 'nonzero inverse')
    return pow(a, -1, p)


def mul(a, b, p):
    event('polynomial_multiply')
    c = [0]*(len(a)+len(b)-1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            c[i+j] = (c[i+j]+x*y) % p
    return trim(c)


def divrem(a, b, p):
    event('polynomial_division')
    require(b != [0], 'nonzero polynomial divisor')
    a = trim(a); q = [0]*max(1, len(a)-len(b)+1); bi = inv(b[-1], p)
    while a != [0] and len(a) >= len(b):
        j = len(a)-len(b); c = a[-1]*bi % p; q[j] = c
        for i, x in enumerate(b):
            a[i+j] = (a[i+j]-c*x) % p
        a = trim(a)
    return trim(q), a


def rem(a, u, p):
    return divrem(a, u, p)[1]


def exact(a, b, p):
    q, r = divrem(a, b, p); require(r == [0], 'exact polynomial division')
    return q


def power(a, n, p):
    r = [1]
    while n:
        if n & 1:
            r = mul(r, a, p)
        n >>= 1
        if n:
            a = mul(a, a, p)
    return r


def powmod(a, n, u, p):
    event('quotient_power'); event('quotient_exponent_bits', n.bit_length())
    r = rem([1], u, p); a = rem(a, u, p)
    while n:
        if n & 1:
            r = rem(mul(r, a, p), u, p)
        n >>= 1
        if n:
            a = rem(mul(a, a, p), u, p)
    return r


def inverse_mod(a, u, p):
    event('polynomial_extended_euclid')
    r0, r1, s0, s1 = u, rem(a, u, p), [0], [1]
    while r1 != [0]:
        q, r = divrem(r0, r1, p)
        r0, r1, s0, s1 = r1, r, s1, sub(s0, mul(q, s1, p), p)
    require(len(r0) == 1 and r0[0] != 0, 'coprime CRT factors')
    return rem(scale(s0, inv(r0[0], p), p), u, p)


def evaluate(a, x, p):
    event('polynomial_evaluation')
    r = 0
    for c in reversed(a):
        r = (r*x+c) % p
    return r


def valuation(a, x, p):
    if a == [0]:
        return float('inf'), [0]
    n = 0; linear = [(-x) % p, 1]
    while True:
        q, r = divrem(a, linear, p)
        if r != [0]:
            return n, a
        n += 1; a = q


def curve_data(curve):
    require(type(curve) is dict and set(curve) == {'p', 'a', 'b'}, 'curve representation')
    p = field(curve['p']); require(p > 3, 'short Weierstrass characteristic')
    a, b = scalar(curve['a'], p), scalar(curve['b'], p)
    require((4*a*a*a+27*b*b) % p != 0, 'nonsingular curve')
    return p, [b, a, 0, 1]


def verify_quotient_witness(U, t, s, e, curve=None):
    event('quotient_witness_verification')
    p, u = modulus(U); interval(p, t, s); k = len(u)-1
    if curve is not None:
        cp, f = curve_data(curve); require(cp == p, 'curve quotient field match')
    require(type(e) is list, 'idempotent list')
    if not k:
        require(e == [], 'empty quotient witnesses'); return True
    require(len(e) == s, 'idempotent bit count')
    weighted = [t]
    for j, v in enumerate(e):
        v = canonical(v, p); require(len(v) <= k, 'reduced idempotent')
        require(rem(sub(mul(v, v, p), v, p), u, p) == [0], 'idempotence')
        weighted = add(weighted, scale(v, pow(2, j, p), p), p)
    n = rem(sub([0, 1], weighted, p), u, p)
    require(powmod(n, k, u, p) == [0], 'interval nilpotence')
    if curve is not None:
        T = rem(mul(f, sub(powmod(f, (p-1)//2, u, p), [1], p), p), u, p)
        require(powmod(T, k, u, p) == [0], 'rational ordinate support')
    return True
